<div class="page-heading"><div><span class="eyebrow">BANK RECONCILIATION</span><h1>Match your money</h1><p>Connect bank statement transactions to paid income and expenses.</p></div><button class="button primary" data-dialog="bank-import-dialog"><?= icon('upload') ?>Import CSV</button></div>
<div class="table-wrap"><table><thead><tr><th>Bank transaction</th><th>Date</th><th class="number">Amount</th><th>Matching entry</th></tr></thead><tbody><?php foreach($transactions as $t): ?><tr><td class="strong"><?= e($t['description']) ?></td><td class="nowrap"><?= short_date($t['transaction_date']) ?></td><td class="number <?= $t['amount']>0?'positive':'' ?>"><?= money($t['amount']) ?></td><td><form class="inline-form" method="post" action="<?= e(url('bank-match')) ?>"><?= csrf_field() ?><input type="hidden" name="id" value="<?= $t['id'] ?>"><?php if($t['entry_id']): ?><a class="text-link" href="<?= e(url('entry',['id'=>$t['entry_id']])) ?>"><?= icon('check-check') ?><?= e($t['entry_description']) ?></a><button class="icon-button" name="action" value="unmatch" title="Remove match" aria-label="Remove match"><?= icon('x') ?></button><?php else: ?><select name="entry_id" required aria-label="Match <?= e($t['description']) ?>"><option value="">Choose paid entry</option><?php foreach($entries as $entry): if((int)$entry['amount']*($entry['type']==='income'?1:-1)!==(int)$t['amount'])continue; ?><option value="<?= $entry['id'] ?>"><?= e($entry['description']) ?> / <?= short_date($entry['paid_on']) ?></option><?php endforeach ?></select><button class="icon-button positive" name="action" value="match" title="Match transaction" aria-label="Match transaction"><?= icon('check') ?></button><?php endif ?></form></td></tr><?php endforeach ?><?php if(!$transactions): ?><tr><td colspan="4"><div class="empty-state"><?= icon('refresh-cw') ?><h3>Ready to reconcile</h3><p>Import a bank statement to begin matching your transactions.</p></div></td></tr><?php endif ?></tbody></table></div>
<dialog id="bank-import-dialog"><div class="dialog-heading"><h2>Import bank statement</h2><button class="icon-button" data-close-dialog title="Close" aria-label="Close"><?= icon('x') ?></button></div><form method="post" enctype="multipart/form-data" class="stack-form" action="<?= e(url('bank-import')) ?>"><?= csrf_field() ?><label>CSV file<input type="file" name="statement" accept=".csv" required><small>Up to 2 MB / 2,000 transactions / <?= e(workspace()['currency']) ?> only</small></label><p class="fine-print">Required columns: date, description, amount, reference. Use YYYY-MM-DD dates and negative amounts for expenses. Each bank reference must be unique.</p><a class="text-link" href="<?= e(asset('statement-template.csv')) ?>" download><?= icon('download') ?>Download CSV template</a><button class="button primary"><?= icon('upload') ?>Import transactions</button></form></dialog>
